            var auto=Create(Path.Combine(path,"autoplay"));Good(auto,"new_game","bond");var ac=new PythonShiftCommand{kind="start_autoplay",autoplay_objective="bond",autoplay_mode="clear",autoplay_days=3,request_id=Guid.NewGuid().ToString("N"),instance_id=auto.Simulation.State.instance_id,expected_revision=auto.Simulation.State.revision};check(StandaloneDispatchConversationSmoke.Raw(auto,JsonUtility.ToJson(ac)).result==UnityEngine.Networking.UnityWebRequest.Result.Success,"Autoplay start failed");int steps=0;while(auto.Simulation.State.autoplay.running && steps++<1000)Good(auto,"step_autoplay");check(auto.BondEndingPending && !auto.Simulation.State.autoplay.running,"Autoplay did not stop at ending");Good(auto,"save_game",slot:8);Good(auto,"load_game",slot:8);check(auto.BondEndingPending && !auto.Simulation.State.autoplay.running,"Autoplay restarted on load");
