        }
        void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
        void Fail(Exception e){if(failed)return;failed=true;File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Debug.LogException(e);Application.Quit(1);}
        void Log(string m,string stack,LogType type){if(type==LogType.Error || type==LogType.Exception || type==LogType.Assert)Fail(new Exception(m+"\n"+stack));}
        void OnDestroy(){Application.logMessageReceived-=Log;}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--catcafe-bond-ending-check");if(i<0)return;var qa=new GameObject("Ending verification").AddComponent<StandaloneBondEndingSmoke>();DontDestroyOnLoad(qa);qa.output=Path.GetFullPath(args[i+1]);Directory.CreateDirectory(qa.output);Application.runInBackground=true;Application.logMessageReceived+=qa.Log;try{qa.checks=BackendChecks(Path.Combine(qa.output,"cases"),args.Contains("--bond-ending-restart"));qa.StartCoroutine(qa.Guard());}catch(Exception e){qa.Fail(e);}}
        IEnumerator Guard(){var run=Run();while(true){bool more;try{more=run.MoveNext();}catch(Exception e){Fail(e);yield break;}if(!more)yield break;yield return run.Current;}}
