sume.interactable,"Closed ending not resumable");preview.GetComponent<PythonGoalPanel>().Continue();yield return null;Check(ui.Showing && p.node==1,"Resume reset line");ui.Panel.GetComponentsInChildren<Button>(true).Single(x=>x.name=="バックログ").onClick.Invoke();yield return null;Check(ui.HistoryScroll.content.rect.height>=ui.HistoryScroll.content.GetComponent<Text>().preferredHeight-1,"Backlog clipped");yield return null;ui.Panel.GetComponentsInChildren<Button>(true).Single(x=>x.name=="バックログ").onClick.Invoke();yield return null;
            p.node=CafeBondEnding.Lines(CafeBondEnding.Record(b.Simulation.State),"猫").Length;ui.Refresh();yield return null;ui.Next();yield return null;Check(ui.Outro.activeSelf && !ui.Showing && p.completed,"Outro not shown");Check(state==JsonUtility.ToJson(b.Simulation.State),"Ending changed gameplay");Good(b,"save_game",slot:7);Good(b,"continue_bond_goal");yield return new WaitForSecondsRealtime(2.2f);Check(!ui.Outro.activeSelf && !b.Simulation.BondWaiting,"Continue did not close outro");Good(b,"load_game",slot:7);yield return new WaitForSecondsRealtime(2.2f);Check(ui.Outro.activeSelf && b.BondEnding.progress.completed,"Completed result save not restored");
            SceneManager.LoadScene("CatCafeTitle");yield return new WaitForSecondsRealtime(2);var extra=FindObjectOfType<PythonTitleScreen>().GetComponent<TitleExtraPanel>();extra.Open();extra.Panel.transform.Find("エンディング").GetComponent<Button>().onClick.Invoke();yield return null;extra.OpenReplay(CafeBondEnding.Id+"/"+CafePopularityEnding.Branch);yield return null;Check(extra.Replay.Showing,"Ending replay locked");string before=JsonUtility.ToJson(b.Simulation.State);extra.Replay.Next();yield return null;extra.Replay.Close();Check(before==JsonUtility.ToJson(b.Simulation.State),"Replay changed gameplay");File.WriteAllText(Path.Combine(output,"result.txt"),"PASS: "+checks+" bond ending checks; zero Unity errors.");Setup(b);SceneManager.LoadScene("CatCafePythonState");
        }
